refentry.refsect1:
&reftitle.description;
public Dom\ElementnullDom\ParentNode::querySelector stringselectors
selectors で指定された CSS セレクタにマッチする、最初の要素を返します。

&reftitle.parameters;


  selectors


    ひとつ以上の CSS セレクタを含む文字列

  &reftitle.examples;

   Dom\ParentNode::querySelector の例


<?php
$dom = Dom\HTMLDocument::createFromString(
    '<!DOCTYPE html><body><div id="container"><p class="item">First</p><p class="item">Second</p></div></body>',
    LIBXML_NOERROR
);

$container = $dom->getElementById('container');

$firstItem = $container->querySelector('.item');
echo $firstItem->textContent, "\n";

echo $container->querySelector('p.item')->textContent, "\n";

?>


   &example.outputs;


First
First
